```

back:
// Why: A subclass of Error inherits message and stack, but its name stays "Error" unless
// you set it. Callers can then check `error instanceof ValidationError`.
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Error
function validateUser(user) {
  if (!user.name) throw new ValidationError("name is required");
  if (!user.email) throw new ValidationError("email is required");
  return true;
}

class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = "ValidationError";
  }
}

